@Controller({ path: 'chat', version: '1' })
export class ChatController {
  @Post('completions')
  sendCompletion(@Req() req: Request,
                 @Body() dto: ChatCompletionDto) {
    const { at } = req.user as SessionUser;
    return this.chatService.sendCompletion(dto, at);
  }
}
